      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1.2rem;
    }

    .member-card {
      min-width: 0;
      display: flex;
      flex-direction: column;
      padding: 1.6rem;
      border: 1px solid var(--line);
      border-radius: 22px;
      background: var(--card);
