      border-radius: 12px;
      background: var(--soft);
      font-size: .9rem;
    }
    .detail-block strong {
      display: block;
      margin-bottom: .2rem;
      font-size: .72rem;
      letter-spacing: .1em;
      text-transform: uppercase;
