    .detail-block p { margin: 0; color: var(--muted); }

    .fun-fact {
      margin: .15rem 0 1rem;
      color: var(--muted);
      font-size: .88rem;
    }

    .hot-take {
      margin: auto 0 0;
      padding: .85rem 1rem;
      border-radius: 12px;
      background: var(--accent);
      color: #FFFFFF;
      font-size: .9rem;
      font-weight: 650;
      line-height: 1.5;
    }

    .future-section { padding-top: 2rem; }
    .future-intro {
      max-width: 760px;
      margin: .8rem 0 2rem;
      color: var(--muted);
      font-size: 1.08rem;
    }

    .future-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.2rem;
    }
    .future-panel {
      padding: 1.6rem;
      border: 1px solid var(--line);
      border-radius: 20px;
      background: var(--card);
      box-shadow: var(--shadow);
    }
    .future-panel h3 {
      margin-bottom: 1rem;
      font-size: 1.2rem;
      letter-spacing: -.03em;
    }
    .future-panel ul {
      display: grid;
      gap: .75rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }
    .future-panel li {
      position: relative;
      padding-left: 1.3rem;
      color: var(--muted);
    }
    .future-panel li::before {
      content: "↗";
      position: absolute;
      left: 0;
      color: var(--accent);
      font-weight: 800;
    }
    .debate {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      margin-top: 1.2rem;
    }
    .debate-side {
      padding: 1.1rem;
      border-radius: 14px;
      background: var(--soft);
    }
    .debate-side strong {
      display: block;
      margin-bottom: .45rem;
      font-size: .8rem;
      letter-spacing: .08em;
      text-transform: uppercase;
    }
    .debate-side p { margin: 0; color: var(--muted); font-size: .9rem; }

    .closing-note {
      margin: 1.2rem 0 0;
      padding: 1.2rem 1.4rem;
      border-left: 3px solid var(--accent);
      color: var(--muted);
      background: var(--soft);
    }

    footer {
      border-top: 1px solid var(--line);
      color: var(--muted);
      text-align: center;
      font-size: .82rem;
    }
    .footer-inner { padding-block: 1.5rem; }
    footer p { margin: 0; }

    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }
