  <header class="site-header">
    <div class="header-inner">
      <div class="brand"><div class="brand-mark" aria-hidden="true">&lt;/&gt;</div><div><p class="brand-name">Build &amp; Beyond</p><span class="brand-kicker">Paderborn · Computer Science</span></div></div>
      <div class="header-actions"><nav aria-label="Main navigation"><a href="#team">The team</a><a href="#future-of-se">Our outlook</a></nav><button id="theme-toggle" type="button" aria-label="Switch to night mode"><span aria-hidden="true">☾</span></button></div>
