main{padding-block:3rem 4rem}
.hero{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(16rem,.6fr);align-items:end;gap:2rem;padding:2rem 0 3rem;border-bottom:1px solid var(--line)}
.eyebrow{display:inline-flex;align-items:center;gap:.5rem;margin:0 0 .5rem;color:var(--muted);font-size:.75rem;font-weight:750;letter-spacing:.125rem;text-transform:uppercase}
.eyebrow::before{content:"";width:1.5rem;height:.125rem;background:var(--accent)}
h1,h2,h3{margin-top:0;font-weight:750}
h1{max-width:70ch;margin-bottom:.5rem;font-size:2.5rem;line-height:1.15;letter-spacing:-.075rem}
h1 span{display:block;color:var(--muted);font-weight:480}
.hero-copy{max-width:65ch;margin:0;color:var(--muted);font-size:1.125rem}
.hero-note{padding:1.5rem;border:1px solid var(--line);border-radius:1rem;background:var(--soft)}
.hero-note strong{display:block;margin-bottom:.5rem;font-size:.8rem;letter-spacing:.125rem;text-transform:uppercase}
.hero-note p{margin:0;color:var(--muted);font-size:.95rem}
.section-heading{display:flex;align-items:end;justify-content:space-between;gap:2rem;margin:3rem 0 1.5rem}
.section-heading h2{margin:0;font-size:1.75rem;line-height:1.2;letter-spacing:-.05rem}
.section-heading>p{max-width:55ch;margin:0;color:var(--muted);font-size:.95rem}
.team-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(16rem,1fr));gap:1.5rem}
.member-card{min-width:0;display:flex;flex-direction:column;padding:1.5rem;border:1px solid var(--line);border-radius:1.5rem;background:var(--card);box-shadow:var(--shadow)}
.member-photo{width:8rem;height:8rem;margin-bottom:1.5rem;border:1px solid var(--line);border-radius:50%;object-fit:cover;background:var(--soft)}
.member-card h3{margin:0 0 .5rem;font-size:1.25rem;line-height:1.3;letter-spacing:-.025rem}
.study{margin:0 0 1rem;color:var(--muted);font-size:.875rem;font-weight:600}
.bio{margin:0 0 1rem;color:var(--text);font-size:.9375rem}
.detail-block{margin:0 0 1rem;padding:1rem;border-radius:1rem;background:var(--soft);font-size:.9rem}
.detail-block strong{display:block;margin-bottom:.5rem;font-size:.75rem;letter-spacing:.1rem;text-transform:uppercase}
.detail-block p{margin:0;color:var(--muted);font-size:.9rem}
.fun-fact{margin:0 0 1rem;color:var(--muted);font-size:.875rem}
.hot-take{margin:auto 0 0;padding:1rem;border-radius:1rem;background:var(--accent);color:#FFFFFF;font-size:.9rem;font-weight:650;line-height:1.5}
.future-section{padding-top:1.5rem}
.future-intro{max-width:70ch;margin:.5rem 0 2rem;color:var(--muted);font-size:1rem}
.future-grid{display:grid;grid-template-columns:1fr 1fr;gap:1.5rem}
.future-panel{padding:1.5rem;border:1px solid var(--line);border-radius:1.5rem;background:var(--card);box-shadow:var(--shadow)}
.future-panel h3{margin:0 0 1rem;font-size:1.25rem;letter-spacing:-.025rem}
.future-panel ul{display:grid;gap:1rem;margin:0;padding:0;list-style:none}
.future-panel li{position:relative;padding-left:1.5rem;color:var(--muted)}
.future-panel li::before{content:"↗";position:absolute;left:0;color:var(--accent);font-weight:800}
.debate{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:1rem}
.debate-side{padding:1rem;border-radius:1rem;background:var(--soft)}
.debate-side strong{display:block;margin-bottom:.5rem;font-size:.8rem;letter-spacing:.075rem;text-transform:uppercase}
.debate-side p{margin:0;color:var(--muted);font-size:.9rem}
.closing-note{margin:1.5rem 0 0;padding:1.5rem;border-left:.25rem solid var(--accent);color:var(--muted);background:var(--soft)}
footer{border-top:1px solid var(--line);color:var(--muted);text-align:center;font-size:.8rem}
.footer-inner{padding-block:1.5rem}
footer p{max-width:none;margin:0}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{transition-duration:.01ms!important;animation-duration:.01ms!important}}
